"""flow.instrument: generated by the graph.py split (P1)."""

from __future__ import annotations

import contextvars
import functools
from pathlib import Path
import sys
import time
from typing import Any

from contextlib import nullcontext

from ..runtime import dependencies, effects, failures, flow_memory, llm, progress as progress_mod, request_audit, stage_history
from ..runtime.persistence import RunPersistence
from ..runtime.progress import StageProgress

# The node wrapper is a no-op unless a progress reporter is enabled. Tests and
# programmatic callers leave it disabled to avoid noisy stdout.
_PROGRESS: StageProgress | None = None


_ACTIVE_PERSISTENCE: contextvars.ContextVar[RunPersistence | None] = contextvars.ContextVar(
    "cfu_active_persistence", default=None
)


def enable_progress(stages: list[str] | None = None) -> None:
    global _PROGRESS
    llm.reset_usage_log()
    _PROGRESS = StageProgress(list(stages) if stages else list(STAGE_ORDER))
    llm.set_stream_callback(_log_stream_progress)


def disable_progress() -> None:
    global _PROGRESS
    _LIVE_LINE.clear()
    _PROGRESS = None
    llm.set_stream_callback(None)


def progress() -> StageProgress | None:
    return _PROGRESS




# Map a node's return value to the gate key that reports its success. Keys are
# the wrapped function names (fn.__name__). Nodes whose gate is not present in
# the map are considered OK unless their own update added errors.
_NODE_TO_GATE: dict[str, str] = {
    "load_context": "load_context",
    "ingest_input": "workload_spec",
    "prepare_c_project_profile_node": "prepare_benchmark",
    "create_benchmark_project_node": "prepare_benchmark",
    "prepare_embench_benchmark_node": "prepare_benchmark",
    "instrument_and_profile": "profile",
    "profile_embench": "profile",
    "extract_hotspot": "hotspot",
    "collect_ir_evidence": "ir",
    "analyze_workload": "analysis",
    "design_contract": "isa",
    "extend_isa": "isa",
    "implement": ("implementation_hw", "implementation_sw"),
    "generate_soc": "hw_build",
    "check_conformance": "hw_conformance",
    "build_sw": "sw_build",
    "simulate": "sim",
    "estimate_cost": "cost",
    "validate_candidate": ("sim", "cost", "validation_pair"),
    "review_and_route": "review",
    "final_report": "final_report",
}


def _node_update(update: Any) -> Any:
    """Return the dict payload of a node update.

    LangGraph nodes may return a plain dict or a ``Command`` whose ``update``
    field holds the dict payload. ``dict`` instances have an ``update`` method,
    so the attribute-based check must come second.
    """
    if isinstance(update, dict):
        return update
    candidate = getattr(update, "update", None)
    if isinstance(candidate, dict):
        return candidate
    return None


def checked_gates(name: str) -> tuple[str, ...]:
    """The gate names a node evaluates. One node may report more than one.

    The free Implement stage writes both ``implementation_hw`` and
    ``implementation_sw``, and both were just evaluated against the current
    inputs, so both must be re-stamped rather than reported stale.
    """
    entry = _NODE_TO_GATE.get(name) or _NODE_TO_GATE.get(name.removesuffix("_node"))
    if entry is None:
        return ()
    return entry if isinstance(entry, tuple) else (entry,)


def _node_ok(update: Any, name: str) -> bool:
    effective = _node_update(update)
    if not isinstance(effective, dict):
        return True
    gates = effective.get("gates", {}) or {}
    reported = [gates.get(key) for key in checked_gates(name)]
    verdicts = [bool(gate.get("ok")) for gate in reported if isinstance(gate, dict) and "ok" in gate]
    return all(verdicts) if verdicts else True


def _update_ok(update: Any, name: str) -> bool:
    """Progress verdict for a finished node: its gate AND its own errors.

    ``errors`` is an append-reducer, so the update carries only this node's
    increment and its length IS the added count. (Subtracting the state's prior
    error total here used to report FAILing rungs as OK whenever the run had
    already seen an error -- for example a repaired hw_build before a failing
    hw_conformance.)
    """
    effective = _node_update(update)
    added = len(effective.get("errors") or []) if isinstance(effective, dict) else 0
    return _node_ok(update, name) and added <= 0


def _audit_context(state):
    """Run-scoped request audit for every model call inside this node.

    A node that runs before the run workspace exists (``load_context``) has no
    model call and needs no recorder; every later node must be covered, so an
    unusable run root fails loudly instead of silently dropping request logs.
    """
    run_root = str(state.get("run_root") or "")
    workdir = str(state.get("workdir") or "")
    if run_root and not run_root.startswith("agents/generated/"):
        raise request_audit.RequestAuditError("audit root must be a run artifact path")
    if not run_root or not workdir or request_audit.active():
        return nullcontext()
    return request_audit.use_request_audit(
        Path(workdir).resolve() / run_root, Path(workdir).resolve()
    )


def _with_flow_memory(state, update, transcript, name, *, history_events=()):
    """Publish verified observations and bounded, outcome-labelled handoffs."""
    if not isinstance(update, dict):
        return update
    try:
        from ..runtime import stage_services

        toolbox = stage_services._toolbox_for_stage(state, name)
        memory = flow_memory.derive_memory(
            state, update, list(transcript or ()), toolbox, node_name=name
        )
        if memory:
            update = {**update, "flow_memory": memory}
        if history_events or state.get("stage_history"):
            history = stage_history.derive_history(
                state, update, list(history_events or ()), toolbox,
                node_name=name, accepted=_update_ok(update, name),
            )
            if history:
                update = {**update, "stage_history": history}
    except (ValueError, OSError):
        # Memory is advisory evidence; a pathological state must not hide the
        # node's own result. Stale entries are revalidated before every use.
        return update
    return update


def _wrap_node(fn):
    @functools.wraps(fn)
    def wrapper(state):
        name = fn.__name__
        llm.set_stage(name)

        def apply_fingerprints(update):
            if not isinstance(update, dict):
                return update
            current = {**state, **update}
            after = dependencies.input_fingerprints(current)
            before = state.get("input_fingerprints") or {}
            if before:
                gates = update.get("gates", state.get("gates") or {})
                # A gate checked by this node is freshly evaluated against the
                # new fingerprint. Other formerly passing gates are not.
                checked = checked_gates(name)
                updated_gates = dependencies.invalidate_changed_gates(gates, before, after)
                if "gates" in update:
                    for key in checked:
                        if key in gates:
                            updated_gates[key] = gates[key]
                if updated_gates != gates:
                    update = {**update, "gates": updated_gates}
            if "gates" in update:
                stamped = {key: dict(value) for key, value in update["gates"].items()}
                for key in checked_gates(name):
                    if key in stamped:
                        stamped[key]["input_sha256"] = after.get(key, "")
                update = {**update, "gates": stamped}
            return {**update, "input_fingerprints": after}

        def call_node():
            # Publish the node's state so runtime/effects.py can run external
            # commands as LangGraph tasks without checkpointing a toolbox. The
            # same context carries the node's exact tool transcripts (for the
            # run memory) and the run-scoped request audit for every model call.
            try:
                audit = _audit_context(state)
                with (effects.use_state(state),
                      flow_memory.collect_tool_transcripts(state) as transcript,
                      stage_history.collect_executions() as history_events,
                      audit):
                    update = fn(state)
                update = apply_fingerprints(update)
                return _with_flow_memory(
                    state, update, transcript, name, history_events=history_events,
                )
            except Exception as exc:
                failures.attach_partial_state(exc, state, source="node_entry", stage=name)
                raise

        def invoke():
            persisted = _ACTIVE_PERSISTENCE.get()
            if persisted is None:
                return call_node()
            # LangGraph checkpoints are not external-effect transactions. Record
            # the pending node *before* executing it; an interrupted node cannot
            # be blindly replayed on --resume, even if only some effects ran.
            attempt = len(persisted.journal._load()["operations"]) + 1
            operation_id = f"node-{name}-{attempt:08d}"
            with persisted.journal.external_operation(
                name, operation_id,
                {"run_id": persisted.run_id, "stage": name},
            ):
                return call_node()

        if _PROGRESS is None:
            return invoke()
        prior_total = _PROGRESS._running_total()
        start = time.monotonic()
        _PROGRESS.begin(name)
        try:
            update = invoke()
        except Exception:
            _LIVE_LINE.clear()
            _PROGRESS.end(
                name,
                ok=False,
                elapsed=time.monotonic() - start,
                tokens=_PROGRESS._running_total() - prior_total,
            )
            raise
        _LIVE_LINE.clear()
        _PROGRESS.end(
            name,
            ok=_update_ok(update, name),
            elapsed=time.monotonic() - start,
            tokens=_PROGRESS._running_total() - prior_total,
        )
        return update

    return wrapper


def _wrapped(fn):
    return _wrap_node(fn) if _PROGRESS is not None else fn


STAGE_ORDER = (
    "load_context",
    "ingest_input",
    "route_input",
    "prepare_benchmark",
    "profile",
    "hotspot",
    "ir",
    "analysis",
    "isa",
    "implement",
    "hw_build",
    "hw_conformance",
    "sw_build",
    "sim",
    "cost",
    "review",
    "final_report",
)




# Live streaming progress is drawn as ONE line rewritten in place on a terminal.
# When stdout is redirected (CI logs, `tee`) intermediate updates are suppressed
# so the log only gets the final per-call token line.
class _LiveLine:
    def __init__(self) -> None:
        self.active = False
        self.width = 0

    @staticmethod
    def is_tty() -> bool:
        try:
            return bool(sys.stdout.isatty())
        except Exception:  # pragma: no cover - exotic stdout replacements
            return False

    def update(self, text: str) -> None:
        if not self.is_tty():
            return
        pad = max(0, self.width - len(text))
        sys.stdout.write("\r" + text + " " * pad)
        sys.stdout.flush()
        self.width = max(self.width, len(text))
        self.active = True

    def clear(self) -> None:
        if self.active and self.is_tty():
            sys.stdout.write("\r" + " " * self.width + "\r")
            sys.stdout.flush()
        self.active = False
        self.width = 0


_LIVE_LINE = _LiveLine()


_LAST_STREAM_CHARS = 0


def _log_stream_progress(payload: dict[str, Any]) -> None:
    """Rewrite one live line while an LLM response streams.

    Keeping it to a single in-place line means a slow generation is visibly
    alive without scrolling the terminal, and a long reasoning phase reports
    growing ``think chars`` instead of repeating ``0 chars``.
    """
    global _LAST_STREAM_CHARS
    if _PROGRESS is None:
        return
    if str(payload.get("phase", "")) == "start":
        _LAST_STREAM_CHARS = 0
        return
    chars = int(payload.get("chars", 0) or 0)
    thinking = int(payload.get("thinking_chars", 0) or 0)
    total = chars + thinking
    if total <= _LAST_STREAM_CHARS:
        return
    _LAST_STREAM_CHARS = total
    stage = progress_mod.stage_label(str(payload.get("stage", "") or "llm"))
    tokens = int(payload.get("tokens", 0) or 0) + int(payload.get("thinking_tokens", 0) or 0)
    if thinking and chars:
        detail = f"{chars} out + {thinking} think chars (~{tokens} tok)"
    elif thinking:
        detail = f"{thinking} think chars (~{tokens} tok)"
    else:
        detail = f"{chars} chars (~{tokens} tok)"
    _LIVE_LINE.update(f"    [llm] {stage} streaming ... {detail}")
